mapper.select:
select rvp.PTL_ID ptlId, ptp.PORTFOLIO_NAME name, rvp.START_ROW startRow, rvp.SUBJECT_CODE_COL subjectCodeCol, rvsm.NAME sumsubMapId, rva.NAME assetSubMapId, rvs.NAME structMapId from RSK_VALTBL_PRT_IMP_MAP rvp left join PTL_PORTFOLIO ptp on ptp.PORTFOLIO_ID = rvp.PTL_ID left join RSK_VALTBL_STRUCT_MAP rvs on rvs.ID = rvp.STRUCT_MAP_ID left join RSK_VALTBL_SUMSUB_MAP rvsm on rvsm.ID = rvp.SUMSUB_MAP_ID left join RSK_VALTBL_ASSET_SUB_MAP rva on rva.ID = rvp.ASSET_SUB_MAP_ID
rvp.PTL_ID in
#{item}

mapper.delete:
delete from RSK_VALTBL_PRT_IMP_MAP rvp where 1=1
and rvp.PTL_ID in
#{item}

mapper.select:
select count(1)
	from RSK_VALTBL_PRT_IMP_MAP rvp
  where rvp.PTL_ID = #{ptlId}

SELECT ASSET_CODE as id, /**行内资产负债编码 **/ ASSET_NAME as text, /**资产名称**/ ASSET_TYPE as col /**资产类型**/ FROM chb_asset_info /**资产要素表**/ WHERE status = 'E' AND ASSET_TYPE = '12' /**资管计划**/
AND (ASSET_CODE LIKE concat(concat('%', #{search}),'%') OR ASSET_NAME LIKE concat(concat('%', #{search}),'%'))
AND ASSET_CODE = #{initValue}
